// OpenDays 2.0.0 - the city libraries' shared opening-days calendar, vendored as source.
// Do not edit this file; update it by replacing it with a newer release (see VENDOR.md and CHANGELOG.md).
namespace OpenDays

open System

module Calendar =
    /// Public holidays on which the libraries are closed.
    let holidays =
        set
            [ DateOnly(2026, 1, 1)
              DateOnly(2026, 1, 19)
              DateOnly(2026, 2, 16)
              DateOnly(2026, 5, 25)
              DateOnly(2026, 7, 3)
              DateOnly(2026, 9, 7)
              DateOnly(2026, 11, 26)
              DateOnly(2026, 12, 25)
              DateOnly(2027, 1, 1)
              DateOnly(2027, 1, 18)
              DateOnly(2027, 2, 15) ]

    /// The libraries are closed on Sundays and on public holidays.
    let isOpen (day: DateOnly) =
        day.DayOfWeek <> DayOfWeek.Sunday && not (holidays.Contains day)

    /// The given day when the libraries are open on it; otherwise the next day on which they are open.
    let onOrAfter (day: DateOnly) =
        Seq.initInfinite (fun offset -> day.AddDays offset) |> Seq.find isOpen

    /// The first day after the given day on which the libraries are open.
    let nextOpen (day: DateOnly) = onOrAfter (day.AddDays 1)
